//Builds a map that maps a character and its weight in the passed input file
//The weight represents how many times it appears within the file
map<char, int> buildWeights(ifstream& inFile){
	map<char, int> chars;
	chars['\n'] = 0;
	string line;
	while(getline(inFile, line)){
		for(int i = 0; i < line.size(); i++){
			//If the character isn't in the map
			if(chars.find(line[i]) == chars.end()){
				chars[line[i]] = 1;
			}
			//If the character is in the map
			else {
				chars[line[i]]++;
			}
		}
		chars['\n']++;
	}
	return chars;
}

#The function used in the code to redeploy the docker containers.
def redeploy_server(self, server_id: str, recipe: dict):
		#Forcefully removes a container and rebuilds it using the provided recipe
		#Shut down
		try:
			container = self.client.containers.get(server_id)
			container.remove(force=True)
		except docker.errors.NotFound:
			pass
		except Exception as e:
			return {"status": "error", "message": f"Failed to remove container: {str(e)}"}

		#Rebuild
		return self.start_server(
			server_id=server_id,
			image_repo=recipe["image"],
			ports=recipe.get("ports", {}),
			env_vars=recipe.get("env", {}),
			container_path=recipe.get("container_path", "/data"),
			network_mode="bridge",
			ram_limit=recipe.get("ram_limit"),
			autostart = False
		)
